/**
 * WEB ONLY — browser Image / picture / HEAD fetch. Not for React Native.
 *
 * OptimizedImage with a muted skeleton/fallback. LRU caches are module-scoped
 * and size-capped; clearOptimizedImageCache() for logout / tenant switch.
 * Effects ignore stale resolutions via signature keys.
 */
import { ImageOff } from 'lucide-react'
import type React from 'react'
import { useEffect, useMemo, useRef, useState } from 'react'

import { cx } from '~/lib/cx'

import { For } from '~/components/utils/for'
import {
  AUTO_DETECT_FORMATS,
  clearOptimizedImageCache,
  detectAutoSources,
  getDetectedSourceCacheKey,
  getImageCacheKey,
  hasLoadedImage,
  preloadImage,
  rememberLoadedImage,
  withCacheVersion,
  withCacheVersionInSrcSet,
  type AutoDetectFormat,
  type CacheVersion,
  type OptimizedImageSource,
} from './optimized-image-cache'
import styles from './optimized-image.module.scss'

// ── Presentation ──────────────────────────────────────────────────────────────

type ImageFit = 'contain' | 'cover' | 'fill' | 'none' | 'scale-down'

const FIT_CLASS: Record<ImageFit, string> = {
  contain: styles.fitContain,
  cover: styles.fitCover,
  fill: styles.fitFill,
  none: styles.fitNone,
  'scale-down': styles.fitScaleDown,
}

// ── Props ─────────────────────────────────────────────────────────────────────

export interface OptimizedImageProps
  extends Omit<
    React.ImgHTMLAttributes<HTMLImageElement>,
    'alt' | 'className' | 'decoding' | 'height' | 'onError' | 'onLoad' | 'src' | 'style' | 'width'
  > {
  src: string
  alt: string
  width?: number
  height?: number
  aspectRatio?: string
  srcSet?: string
  sizes?: string
  sources?: OptimizedImageSource[]
  priority?: boolean
  autoDetectSources?: boolean
  autoDetectFormats?: AutoDetectFormat[]
  responsiveWidths?: number[]
  cacheVersion?: CacheVersion
  loadingStrategy?: 'eager' | 'lazy'
  decodingStrategy?: 'async' | 'auto' | 'sync'
  fetchPriority?: 'auto' | 'high' | 'low'
  fallbackSrc?: string
  fallback?: React.ReactNode
  showSkeleton?: boolean
  fit?: ImageFit
  className?: string
  style?: React.CSSProperties
  imageClassName?: string
  imageStyle?: React.CSSProperties
  skeletonClassName?: string
  fallbackClassName?: string
  onLoad?: (image: HTMLImageElement) => void
  onError?: () => void
}

// ── Component ─────────────────────────────────────────────────────────────────

export function OptimizedImage({
  src,
  alt,
  width,
  height,
  aspectRatio,
  srcSet: srcSetProp,
  sizes,
  sources: sourcesProp,
  priority,
  autoDetectSources,
  autoDetectFormats,
  responsiveWidths,
  cacheVersion,
  loadingStrategy,
  decodingStrategy,
  fetchPriority,
  fallbackSrc,
  fallback,
  showSkeleton = true,
  fit = 'cover',
  className,
  style,
  imageClassName,
  imageStyle,
  skeletonClassName,
  fallbackClassName,
  onLoad: onLoadProp,
  onError: onErrorProp,
  ...imgAttrs
}: OptimizedImageProps) {
  const resolvedSrc = useMemo(() => withCacheVersion(src, cacheVersion), [src, cacheVersion])
  const resolvedFallbackSrc = useMemo(
    () => (fallbackSrc ? withCacheVersion(fallbackSrc, cacheVersion) : undefined),
    [fallbackSrc, cacheVersion],
  )
  const resolvedSrcSet = useMemo(
    () => (srcSetProp ? withCacheVersionInSrcSet(srcSetProp, cacheVersion) : undefined),
    [srcSetProp, cacheVersion],
  )
  const resolvedSources = useMemo(
    () =>
      sourcesProp?.map((s) => ({ ...s, srcSet: withCacheVersionInSrcSet(s.srcSet, cacheVersion) })),
    [sourcesProp, cacheVersion],
  )

  const [detectedSources, setDetectedSources] = useState<OptimizedImageSource[]>([])
  const [activeSrc, setActiveSrc] = useState(resolvedSrc)
  const [loaded, setLoaded] = useState(() =>
    hasLoadedImage(getImageCacheKey(resolvedSrc, resolvedSrcSet, sizes)),
  )
  const [failed, setFailed] = useState(false)
  const [usingFallbackSrc, setUsingFallbackSrc] = useState(false)

  const imageRef = useRef<HTMLImageElement>(null)
  const prevSignatureRef = useRef<string | undefined>(undefined)

  const activeSrcSet = usingFallbackSrc ? undefined : resolvedSrcSet
  const activeSizes = usingFallbackSrc ? undefined : sizes
  const activeCacheKey = getImageCacheKey(activeSrc, activeSrcSet, activeSizes)

  // Reset on src/cacheVersion change
  useEffect(() => {
    let cancelled = false
    const sig = `${src}::${cacheVersion ?? ''}`
    if (prevSignatureRef.current && prevSignatureRef.current !== sig) {
      clearOptimizedImageCache(src)
    }
    prevSignatureRef.current = sig

    const key = getImageCacheKey(resolvedSrc, resolvedSrcSet, sizes)
    const alreadyLoaded = hasLoadedImage(key)
    setActiveSrc(resolvedSrc)
    setLoaded(alreadyLoaded)
    setFailed(false)
    setUsingFallbackSrc(false)

    if (!alreadyLoaded && priority) {
      preloadImage(resolvedSrc, resolvedSrcSet, sizes)
        .then(() => {
          if (cancelled) return
          setLoaded(true)
          setFailed(false)
        })
        .catch(() => undefined)
    }
    return () => {
      cancelled = true
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [src, cacheVersion])

  // Auto-detect sources
  useEffect(() => {
    let cancelled = false
    if (resolvedSources?.length || !autoDetectSources) {
      setDetectedSources([])
      return
    }
    const fmts = (
      autoDetectFormats?.length ? [...new Set(autoDetectFormats)] : AUTO_DETECT_FORMATS
    ) as AutoDetectFormat[]
    const widths = [...(responsiveWidths ?? [])].sort((a, b) => a - b)
    const key = getDetectedSourceCacheKey(src, fmts, widths, sizes, cacheVersion)

    detectAutoSources(src, fmts, widths, sizes, cacheVersion)
      .then((detected) => {
        if (cancelled) return
        if (key === getDetectedSourceCacheKey(src, fmts, widths, sizes, cacheVersion)) {
          setDetectedSources(detected)
        }
      })
      .catch(() => {
        if (cancelled) return
        if (key === getDetectedSourceCacheKey(src, fmts, widths, sizes, cacheVersion)) {
          setDetectedSources([])
        }
      })
    return () => {
      cancelled = true
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [src, sizes, cacheVersion, autoDetectSources, autoDetectFormats, responsiveWidths])

  const discoveredSources = resolvedSources?.length ? resolvedSources : detectedSources
  const ratio = aspectRatio ?? (width && height ? `${width} / ${height}` : undefined)

  const mediaStyle: React.CSSProperties = {
    ...(ratio ? { aspectRatio: ratio } : {}),
    ...style,
    ...imageStyle,
  }

  const fitClass = FIT_CLASS[fit]
  const shouldShowSkeleton = showSkeleton && !loaded && !failed
  const shouldUsePicture = !usingFallbackSrc && Boolean(discoveredSources?.length)

  const mediaClass = cx(
    styles.image,
    fitClass,
    shouldShowSkeleton && styles.skeleton,
    shouldShowSkeleton && skeletonClassName,
    className,
    imageClassName,
  )

  function syncLoaded(img?: HTMLImageElement | null) {
    if (!img || failed) return
    if (img.complete && img.naturalWidth > 0) {
      rememberLoadedImage(activeCacheKey)
      setLoaded(true)
      setFailed(false)
    }
  }

  function handleLoad(e: React.SyntheticEvent<HTMLImageElement>) {
    const img = e.currentTarget
    const finalize = () => {
      rememberLoadedImage(activeCacheKey)
      setLoaded(true)
      setFailed(false)
      onLoadProp?.(img)
    }
    const decode = img.decode?.()
    if (decode) {
      decode.catch(() => undefined).finally(finalize)
    } else {
      finalize()
    }
  }

  function handleError() {
    onErrorProp?.()
    if (!usingFallbackSrc && resolvedFallbackSrc && resolvedFallbackSrc !== activeSrc) {
      setUsingFallbackSrc(true)
      setActiveSrc(resolvedFallbackSrc)
      setLoaded(hasLoadedImage(getImageCacheKey(resolvedFallbackSrc)))
      setFailed(false)
      return
    }
    setFailed(true)
  }

  const imgNode = (
    <img
      {...imgAttrs}
      ref={(el) => {
        ;(imageRef as React.MutableRefObject<HTMLImageElement | null>).current = el
        syncLoaded(el)
      }}
      src={activeSrc}
      alt={alt}
      width={width}
      height={height}
      srcSet={usingFallbackSrc ? undefined : resolvedSrcSet}
      sizes={usingFallbackSrc ? undefined : sizes}
      loading={priority ? 'eager' : (loadingStrategy ?? 'lazy')}
      decoding={priority ? 'sync' : (decodingStrategy ?? 'async')}
      fetchPriority={fetchPriority ?? (priority ? 'high' : undefined)}
      onLoad={handleLoad}
      onError={handleError}
      className={mediaClass}
      style={mediaStyle}
    />
  )

  if (failed) {
    if (fallback) {
      return (
        <span className={cx(styles.fallback, className, fallbackClassName)} style={mediaStyle}>
          {fallback}
        </span>
      )
    }
    if (alt === '') return null
    return (
      <span
        role="img"
        aria-label={alt}
        className={cx(styles.fallback, styles.fallbackPlaceholder, className, fallbackClassName)}
        style={mediaStyle}
      >
        <ImageOff aria-hidden size={20} />
      </span>
    )
  }

  if (shouldUsePicture) {
    return (
      <picture>
        <For each={discoveredSources}>
          {(source) => (
            <source
              key={source.srcSet}
              srcSet={source.srcSet}
              type={source.type}
              media={source.media}
              sizes={source.sizes}
            />
          )}
        </For>
        {imgNode}
      </picture>
    )
  }

  return imgNode
}

@use 'styles' as vz;

.image {
  display: block;
}

.fit-contain {
  object-fit: contain;
}

.fit-cover {
  object-fit: cover;
}

.fit-fill {
  object-fit: fill;
}

.fit-none {
  object-fit: none;
}

.fit-scale-down {
  object-fit: scale-down;
}

.skeleton {
  background: vz.color('muted');
  animation: vz-image-pulse 1.6s vz.ease('in-out') infinite;
}

.fallback {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.fallback-placeholder {
  background: vz.color('muted');
  color: vz.color('muted-foreground');

  svg {
    @include vz.icon(5);
  }
}

@keyframes vz-image-pulse {
  0%,
  100% {
    opacity: 1;
  }

  50% {
    opacity: 0.55;
  }
}

@include vz.motion-reduce {
  .skeleton {
    animation: none;
  }
}

/**
 * Caches and network helpers for <OptimizedImage>.
 * Kept in a component-free module so the component can Fast Refresh.
 */

// ── Types ─────────────────────────────────────────────────────────────────────

export interface OptimizedImageSource {
  srcSet: string
  type?: string
  media?: string
  sizes?: string
}

export type AutoDetectFormat = 'avif' | 'webp'
export type CacheVersion = number | string

// ── Caches ────────────────────────────────────────────────────────────────────

const CACHE_LIMITS = {
  loadedImages: 400,
  pendingRequests: 150,
  assetExistenceChecks: 800,
  discoveredSources: 300,
} as const

const loadedImageCache = new Set<string>()
const pendingImageCache = new Map<string, Promise<void>>()
const assetExistenceCache = new Map<string, Promise<boolean>>()
const discoveredSourceCache = new Map<string, Promise<OptimizedImageSource[]>>()
const RASTER_EXTENSIONS = new Set(['avif', 'jpeg', 'jpg', 'png', 'webp'])
export const AUTO_DETECT_FORMATS: AutoDetectFormat[] = ['avif', 'webp']

function trimSetCache(cache: Set<string>, max: number) {
  while (cache.size > max) {
    const k = cache.values().next().value as string | undefined
    if (k === undefined) return
    cache.delete(k)
  }
}

function trimMapCache<K, V>(cache: Map<K, V>, max: number) {
  while (cache.size > max) {
    const k = cache.keys().next().value as K | undefined
    if (k === undefined) return
    cache.delete(k)
  }
}

function lruGet<K, V>(cache: Map<K, V>, key: K): V | undefined {
  const v = cache.get(key)
  if (v === undefined) return undefined
  cache.delete(key)
  cache.set(key, v)
  return v
}

function lruSet<K, V>(cache: Map<K, V>, key: K, value: V, max: number) {
  cache.delete(key)
  cache.set(key, value)
  trimMapCache(cache, max)
}

export function hasLoadedImage(key: string): boolean {
  if (!loadedImageCache.has(key)) return false
  loadedImageCache.delete(key)
  loadedImageCache.add(key)
  return true
}

export function rememberLoadedImage(key: string) {
  loadedImageCache.delete(key)
  loadedImageCache.add(key)
  trimSetCache(loadedImageCache, CACHE_LIMITS.loadedImages)
}

export function withCacheVersion(url: string, v?: CacheVersion): string {
  if (v === undefined || v === null || v === '') return url
  const [noHash, hash = ''] = url.split('#', 2)
  const [path, query = ''] = noHash.split('?', 2)
  const p = new URLSearchParams(query)
  p.set('__imgv', String(v))
  return `${path}?${p}${hash ? `#${hash}` : ''}`
}

export function withCacheVersionInSrcSet(srcSet: string, v?: CacheVersion): string {
  if (!srcSet || v === undefined || v === null || v === '') return srcSet
  return srcSet
    .split(',')
    .map((c) => {
      const t = c.trim()
      if (!t) return ''
      const [url, ...desc] = t.split(/\s+/)
      return [withCacheVersion(url, v), ...desc].join(' ')
    })
    .filter(Boolean)
    .join(', ')
}

function normalizeDetectionUrl(src: string): URL | undefined {
  if (typeof window === 'undefined' || !src) return undefined
  if (src.startsWith('data:') || src.startsWith('blob:')) return undefined
  try {
    const url = new URL(src, window.location.origin)
    if (url.origin !== window.location.origin) return undefined
    return url
  } catch {
    return undefined
  }
}

function getBaseImageParts(src: string) {
  const url = normalizeDetectionUrl(src)
  if (!url) return undefined
  const lastDot = url.pathname.lastIndexOf('.')
  const lastSlash = url.pathname.lastIndexOf('/')
  if (lastDot <= lastSlash) return undefined
  const ext = url.pathname.slice(lastDot + 1).toLowerCase()
  if (!RASTER_EXTENSIONS.has(ext)) return undefined
  return { basePath: url.pathname.slice(0, lastDot), extension: ext, search: url.search, hash: url.hash }
}

function buildVariantUrl(src: string, format: string, width?: number, v?: CacheVersion) {
  const parts = getBaseImageParts(src)
  if (!parts) return undefined
  const widthSuffix = width ? `-${width}` : ''
  return withCacheVersion(
    `${parts.basePath}${widthSuffix}.${format}${parts.search}${parts.hash}`,
    v,
  )
}

export function getDetectedSourceCacheKey(
  src: string,
  formats: AutoDetectFormat[],
  responsiveWidths: number[],
  sizes?: string,
  v?: CacheVersion,
): string {
  return JSON.stringify({ src, formats, responsiveWidths, sizes: sizes ?? '', cacheVersion: v ?? '' })
}

function checkAssetExists(url: string): Promise<boolean> {
  const cached = lruGet(assetExistenceCache, url)
  if (cached) return cached
  const p = fetch(url, { method: 'HEAD', credentials: 'omit' })
    .then((r) => r.ok)
    .catch(() => false)
  lruSet(assetExistenceCache, url, p, CACHE_LIMITS.assetExistenceChecks)
  return p
}

export async function detectAutoSources(
  src: string,
  formats: AutoDetectFormat[],
  responsiveWidths: number[],
  sizes?: string,
  v?: CacheVersion,
): Promise<OptimizedImageSource[]> {
  if (typeof window === 'undefined') return []
  if (!getBaseImageParts(src)) return []
  const key = getDetectedSourceCacheKey(src, formats, responsiveWidths, sizes, v)
  const cached = lruGet(discoveredSourceCache, key)
  if (cached) return cached

  const detection = (async () => {
    const sources: OptimizedImageSource[] = []
    for (const format of formats) {
      if (responsiveWidths.length > 0) {
        const candidates = await Promise.all(
          responsiveWidths.map(async (w) => {
            const url = buildVariantUrl(src, format, w, v)
            if (!url) return undefined
            return (await checkAssetExists(url)) ? `${url} ${w}w` : undefined
          }),
        )
        const srcSet = candidates.filter(Boolean).join(', ')
        if (srcSet) {
          sources.push({ srcSet, type: `image/${format}`, sizes })
          continue
        }
      }
      const url = buildVariantUrl(src, format, undefined, v)
      if (url && (await checkAssetExists(url))) {
        sources.push({ srcSet: url, type: `image/${format}`, sizes })
      }
    }
    return sources
  })().catch((err) => {
    discoveredSourceCache.delete(key)
    throw err
  })

  lruSet(discoveredSourceCache, key, detection, CACHE_LIMITS.discoveredSources)
  return detection
}

export function clearOptimizedImageCache(match?: string | RegExp | ((k: string) => boolean)) {
  const test =
    typeof match === 'function'
      ? match
      : match instanceof RegExp
        ? (k: string) => match.test(k)
        : typeof match === 'string'
          ? (k: string) => k.includes(match)
          : () => true

  for (const k of Array.from(loadedImageCache)) if (test(k)) loadedImageCache.delete(k)
  for (const k of Array.from(pendingImageCache.keys())) if (test(k)) pendingImageCache.delete(k)
  for (const k of Array.from(assetExistenceCache.keys())) if (test(k)) assetExistenceCache.delete(k)
  for (const k of Array.from(discoveredSourceCache.keys())) if (test(k)) discoveredSourceCache.delete(k)
}

export function getImageCacheKey(src: string, srcSet?: string, sizes?: string): string {
  return `${src}::${srcSet ?? ''}::${sizes ?? ''}`
}

export function preloadImage(src: string, srcSet?: string, sizes?: string): Promise<void> {
  if (typeof window === 'undefined' || !src) return Promise.resolve()
  const key = getImageCacheKey(src, srcSet, sizes)
  if (hasLoadedImage(key)) return Promise.resolve()
  const pending = lruGet(pendingImageCache, key)
  if (pending) return pending
  const p = new Promise<void>((resolve, reject) => {
    let done = false
    const img = new window.Image()
    const res = () => { if (done) return; done = true; rememberLoadedImage(key); pendingImageCache.delete(key); resolve() }
    const rej = () => { if (done) return; done = true; pendingImageCache.delete(key); reject(new Error(`Failed to preload: ${src}`)) }
    img.onload = res; img.onerror = rej
    if (srcSet) img.srcset = srcSet
    if (sizes) img.sizes = sizes
    img.decoding = 'async'; img.src = src
    if (img.complete && img.naturalWidth > 0) res()
  })
  lruSet(pendingImageCache, key, p, CACHE_LIMITS.pendingRequests)
  return p
}
